     "t": "code",
     "lang": "python",
     "code": "def validate_schema(data, schema):\n    errors = []\n    \n    def _validate(obj, sch, path=\"\"):\n        if \"type\" in sch:\n            type_map = {\"string\": str, \"integer\": int, \"number\": (int, float),\n                        \"boolean\": bool, \"array\": list, \"object\": dict}\n            expected = type_map.get(sch[\"type\"])\n            if expected and not isinstance(obj, expected):\n                errors.append(f\"{path}: expected {sch['type']}, got {type(obj).__name__}\")\n                return\n        \n        if sch.get(\"type\") == \"object\" and \"properties\" in sch:\n            for key, prop_schema in sch[\"properties\"].items():\n                if key in sch.get(\"required\", []) and key not in obj:\n                    errors.append(f\"{path}.{key}: required field missing\")\n                elif key in obj:\n                    _validate(obj[key], prop_schema, f\"{path}.{key}\")\n        \n        if sch.get(\"type\") == \"array\" and \"items\" in sch:\n            for i, item in enumerate(obj):\n                _validate(item, sch[\"items\"], f\"{path}[{i}]\")\n    \n    _validate(data, schema)\n    return errors if errors else None\n\nschema = {\n    \"type\": \"object\",\n    \"required\": [\"name\", \"age\"],\n    \"properties\": {\n        \"name\": {\"type\": \"string\"},\n        \"age\": {\"type\": \"integer\"},\n        \"tags\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}}\n    }\n}\nprint(validate_schema({\"name\": \"Alice\", \"age\": 30, \"tags\": [\"ml\"]}, schema))\nprint(validate_schema({\"name\": 123}, schema))",
