     "code": "import time\n\nclass MiddlewareChain:\n    def __init__(self):\n        self.middlewares = []\n    \n    def add(self, middleware):\n        self.middlewares.append(middleware)\n        return self\n    \n    def execute(self, request, handler):\n        def build_chain(index):\n            if index >= len(self.middlewares):\n                return handler\n            current = self.middlewares[index]\n            next_handler = build_chain(index + 1)\n            return lambda req: current(req, next_handler)\n        return build_chain(0)(request)\n\ndef logging_middleware(request, next_handler):\n    print(f\"  [LOG] Processing: {request}\")\n    response = next_handler(request)\n    print(f\"  [LOG] Response: {response}\")\n    return response\n\ndef timing_middleware(request, next_handler):\n    start = time.time()\n    response = next_handler(request)\n    print(f\"  [TIME] {time.time() - start:.4f}s\")\n    return response\n\ndef auth_middleware(request, next_handler):\n    if request.get(\"auth\"):\n        return next_handler(request)\n    return {\"error\": \"Unauthorized\"}\n\nchain = MiddlewareChain()\nchain.add(logging_middleware).add(timing_middleware).add(auth_middleware)\n\nhandler = lambda req: {\"status\": \"ok\", \"data\": req.get(\"data\")}\nresult = chain.execute({\"auth\": True, \"data\": \"hello\"}, handler)\nprint(f\"Final: {result}\")",
