     "code": "import json\nfrom datetime import datetime\n\nclass RequestLogger:\n    def __init__(self):\n        self.logs = []\n    \n    def log_request(self, method, path, body=None, headers=None):\n        entry = {\n            \"timestamp\": datetime.now().isoformat(),\n            \"method\": method,\n            \"path\": path,\n            \"body_size\": len(json.dumps(body)) if body else 0,\n            \"headers\": dict(headers) if headers else {}\n        }\n        self.logs.append(entry)\n        return entry\n    \n    def log_response(self, status_code, body=None, duration_ms=None):\n        entry = {\n            \"timestamp\": datetime.now().isoformat(),\n            \"status\": status_code,\n            \"body_size\": len(json.dumps(body)) if body else 0,\n            \"duration_ms\": duration_ms\n        }\n        self.logs.append(entry)\n        return entry\n    \n    def get_stats(self):\n        return {\n            \"total_logs\": len(self.logs),\n            \"status_codes\": {l.get(\"status\"): sum(1 for x in self.logs if x.get(\"status\") == l.get(\"status\"))\n                           for l in self.logs if \"status\" in l}\n        }\n\nlogger = RequestLogger()\nlogger.log_request(\"POST\", \"/api/predict\", {\"data\": [1, 2, 3]})\nlogger.log_response(200, {\"prediction\": 0.95}, duration_ms=45)\nprint(json.dumps(logger.logs, indent=2))",
