     "code": "def paginate(items, page=1, per_page=10):\n    total = len(items)\n    total_pages = (total + per_page - 1) // per_page\n    start = (page - 1) * per_page\n    end = start + per_page\n    \n    return {\n        \"data\": items[start:end],\n        \"pagination\": {\n            \"page\": page,\n            \"per_page\": per_page,\n            \"total\": total,\n            \"total_pages\": total_pages,\n            \"has_next\": page < total_pages,\n            \"has_prev\": page > 1,\n        }\n    }\n\nitems = list(range(1, 46))\nfor page in [1, 2, 5]:\n    result = paginate(items, page=page, per_page=10)\n    print(f\"Page {page}: {result['data']} ({result['pagination']['total_pages']} pages)\")",
