     "code": "import sys\n\nclass CLIParser:\n    def __init__(self, description=\"\"):\n        self.description = description\n        self.args = {}\n        self.flags = {}\n    \n    def add_argument(self, name, type=str, default=None, required=False, help=\"\"):\n        self.args[name] = {\"type\": type, \"default\": default, \"required\": required, \"help\": help}\n    \n    def add_flag(self, name, help=\"\"):\n        self.flags[name] = {\"help\": help}\n    \n    def parse(self, argv=None):\n        argv = argv or sys.argv[1:]\n        result = {k: v[\"default\"] for k, v in self.args.items()}\n        \n        i = 0\n        while i < len(argv):\n            key = argv[i].lstrip('-')\n            if key in self.flags:\n                result[key] = True\n                i += 1\n            elif key in self.args and i + 1 < len(argv):\n                result[key] = self.args[key][\"type\"](argv[i + 1])\n                i += 2\n            else:\n                i += 1\n        \n        for name, spec in self.args.items():\n            if spec[\"required\"] and result.get(name) is None:\n                raise ValueError(f\"--{name} is required\")\n        return result\n\nparser = CLIParser(\"ML Training\")\nparser.add_argument(\"epochs\", type=int, default=10)\nparser.add_argument(\"lr\", type=float, default=0.001)\nparser.add_flag(\"verbose\")\nresult = parser.parse([\"--epochs\", \"50\", \"--lr\", \"0.01\", \"--verbose\"])\nprint(result)",
