     "t": "code",
     "lang": "python",
     "code": "def parse_simple_yaml(text):\n    result = {}\n    stack = [(result, -1)]\n    \n    for line in text.split('\\n'):\n        stripped = line.strip()\n        if not stripped or stripped.startswith('#'):\n            continue\n        \n        indent = len(line) - len(line.lstrip())\n        \n        while stack and stack[-1][1] >= indent:\n            stack.pop()\n        \n        if ':' in stripped:\n            key, _, value = stripped.partition(':')\n            key = key.strip()\n            value = value.strip()\n            \n            parent = stack[-1][0]\n            \n            if value:\n                # Try numeric conversion\n                try:\n                    value = int(value)\n                except ValueError:\n                    try:\n                        value = float(value)\n                    except ValueError:\n                        if value.lower() in ('true', 'false'):\n                            value = value.lower() == 'true'\n            else:\n                value = {}\n                stack.append((value, indent))\n            \n            parent[key] = value\n    \n    return result\n\nconfig = \"\"\"\n# ML Config\nmodel:\n  name: resnet50\n  epochs: 100\n  learning_rate: 0.001\ntraining:\n  batch_size: 32\n  use_gpu: true\n\"\"\"\nparsed = parse_simple_yaml(config)\nprint(parsed)",
