     "lang": "python",
     "code": "from collections import defaultdict\n\nclass EventEmitter:\n    def __init__(self):\n        self._listeners = defaultdict(list)\n    \n    def on(self, event, callback):\n        self._listeners[event].append(callback)\n        return self\n    \n    def off(self, event, callback=None):\n        if callback:\n            self._listeners[event].remove(callback)\n        else:\n            del self._listeners[event]\n    \n    def emit(self, event, *args, **kwargs):\n        for callback in self._listeners[event]:\n            callback(*args, **kwargs)\n\nemitter = EventEmitter()\nemitter.on(\"model_trained\", lambda m: print(f\"Model {m} trained!\"))\nemitter.on(\"model_trained\", lambda m: print(f\"Saving {m}...\"))\nemitter.on(\"error\", lambda e: print(f\"Error: {e}\"))\n\nemitter.emit(\"model_trained\", \"ResNet50\")\nemitter.emit(\"error\", \"Out of memory\")",
