     "code": "import hashlib\nimport json\nimport base64\nimport time\n\ndef base64url_encode(data):\n    return base64.urlsafe_b64encode(json.dumps(data).encode()).decode().rstrip('=')\n\ndef create_jwt(payload, secret, expiry_seconds=3600):\n    header = {\"alg\": \"HS256\", \"typ\": \"JWT\"}\n    payload[\"exp\"] = int(time.time()) + expiry_seconds\n    \n    header_b64 = base64url_encode(header)\n    payload_b64 = base64url_encode(payload)\n    \n    signature = hashlib.sha256(f\"{header_b64}.{payload_b64}.{secret}\".encode()).hexdigest()\n    return f\"{header_b64}.{payload_b64}.{signature}\"\n\ndef verify_jwt(token, secret):\n    parts = token.split('.')\n    if len(parts) != 3:\n        return None\n    expected_sig = hashlib.sha256(f\"{parts[0]}.{parts[1]}.{secret}\".encode()).hexdigest()\n    if parts[2] != expected_sig:\n        return None\n    payload = json.loads(base64.urlsafe_b64decode(parts[1] + '=='))\n    if payload.get(\"exp\", 0) < time.time():\n        return None\n    return payload\n\ntoken = create_jwt({\"user\": \"alice\", \"role\": \"admin\"}, \"secret123\")\nprint(f\"Token: {token[:50]}...\")\npayload = verify_jwt(token, \"secret123\")\nprint(f\"Verified: {payload}\")",
