     "code": "import time\nfrom enum import IntEnum\n\nclass LogLevel(IntEnum):\n    DEBUG = 10\n    INFO = 20\n    WARNING = 30\n    ERROR = 40\n    CRITICAL = 50\n\nclass Logger:\n    def __init__(self, name, level=LogLevel.INFO):\n        self.name = name\n        self.level = level\n        self.handlers = []\n    \n    def add_handler(self, handler):\n        self.handlers.append(handler)\n    \n    def _log(self, level, message):\n        if level >= self.level:\n            record = {\n                \"time\": time.strftime(\"%Y-%m-%d %H:%M:%S\"),\n                \"level\": level.name,\n                \"logger\": self.name,\n                \"message\": message\n            }\n            for handler in self.handlers:\n                handler(record)\n    \n    def debug(self, msg): self._log(LogLevel.DEBUG, msg)\n    def info(self, msg): self._log(LogLevel.INFO, msg)\n    def warning(self, msg): self._log(LogLevel.WARNING, msg)\n    def error(self, msg): self._log(LogLevel.ERROR, msg)\n\nconsole_handler = lambda r: print(f\"[{r['time']}] {r['level']:>8} | {r['logger']} | {r['message']}\")\nlogger = Logger(\"ml_pipeline\", LogLevel.INFO)\nlogger.add_handler(console_handler)\nlogger.info(\"Training started\")\nlogger.warning(\"GPU memory low\")\nlogger.debug(\"This won't show\")",
