     "code": "from collections import defaultdict\nimport threading\n\nclass MessageBroker:\n    def __init__(self):\n        self.topics = defaultdict(list)\n        self.lock = threading.Lock()\n    \n    def subscribe(self, topic, callback):\n        with self.lock:\n            self.topics[topic].append(callback)\n    \n    def publish(self, topic, message):\n        with self.lock:\n            subscribers = list(self.topics[topic])\n        for callback in subscribers:\n            callback(topic, message)\n    \n    def unsubscribe(self, topic, callback):\n        with self.lock:\n            self.topics[topic].remove(callback)\n\nbroker = MessageBroker()\nbroker.subscribe(\"model.trained\", lambda t, m: print(f\"  [{t}] Saving: {m}\"))\nbroker.subscribe(\"model.trained\", lambda t, m: print(f\"  [{t}] Logging: {m}\"))\nbroker.subscribe(\"data.updated\", lambda t, m: print(f\"  [{t}] Refreshing: {m}\"))\n\nbroker.publish(\"model.trained\", {\"model\": \"bert\", \"accuracy\": 0.95})\nbroker.publish(\"data.updated\", {\"table\": \"users\"})",
