     "code": "import re\n\nclass TemplateEngine:\n    def __init__(self):\n        self.filters = {\n            \"upper\": str.upper,\n            \"lower\": str.lower,\n            \"title\": str.title,\n            \"len\": len,\n        }\n    \n    def render(self, template, context):\n        # Variable substitution: {{ var }}\n        def replace_var(match):\n            expr = match.group(1).strip()\n            if '|' in expr:\n                var, filter_name = expr.split('|', 1)\n                value = context.get(var.strip(), '')\n                return str(self.filters.get(filter_name.strip(), str)(value))\n            return str(context.get(expr, ''))\n        \n        result = re.sub(r'{{(.+?)}}', replace_var, template)\n        \n        # For loops: {% for item in list %}...{% endfor %}\n        def replace_loop(match):\n            var, list_name, body = match.group(1), match.group(2), match.group(3)\n            items = context.get(list_name, [])\n            return ''.join(self.render(body, {**context, var: item}) for item in items)\n        \n        result = re.sub(r'{%\\s*for\\s+(\\w+)\\s+in\\s+(\\w+)\\s*%}(.+?){%\\s*endfor\\s*%}',\n                       replace_loop, result, flags=re.DOTALL)\n        return result\n\nengine = TemplateEngine()\ntemplate = \"\"\"Hello {{ name | upper }}!\nItems: {% for item in items %}[{{ item }}] {% endfor %}\"\"\"\nprint(engine.render(template, {\"name\": \"alice\", \"items\": [\"a\", \"b\", \"c\"]}))",
