     "code": "import socket\nimport threading\n\nreceived = []\n\ndef serve(sock):\n    conn, _ = sock.accept()\n    with conn:\n        chunk = conn.recv(4096)            # ONE recv, three sends\n        received.append(chunk)\n\nserver = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\nserver.bind((\"127.0.0.1\", 0))\nserver.listen(1)\nport = server.getsockname()[1]\nt = threading.Thread(target=serve, args=(server,))\nt.start()\n\nwith socket.create_connection((\"127.0.0.1\", port)) as c:\n    c.sendall(b\"one\")\n    c.sendall(b\"two\")\n    c.sendall(b\"three\")\nt.join()\nserver.close()\n\nprint(b\"\".join(received))          # Output: b'onetwothree'\nprint(\"message boundaries are gone:\", received[0] != b\"one\")\n# Output: message boundaries are gone: True\n\n# This is why every TCP protocol needs framing: a length prefix, or a delimiter.",
