     "t": "code",
     "lang": "python",
     "code": "import socket\nimport struct\nimport threading\n\ndef send_msg(sock, payload):\n    sock.sendall(struct.pack(\"!I\", len(payload)) + payload)   # 4-byte length first\n\ndef recv_exactly(sock, n):\n    buf = b\"\"\n    while len(buf) < n:\n        chunk = sock.recv(n - len(buf))\n        if not chunk:\n            raise ConnectionError(\"socket closed early\")\n        buf += chunk\n    return buf\n\ndef recv_msg(sock):\n    (length,) = struct.unpack(\"!I\", recv_exactly(sock, 4))\n    return recv_exactly(sock, length)\n\ngot = []\n\ndef serve(sock):\n    conn, _ = sock.accept()\n    with conn:\n        for _ in range(3):\n            got.append(recv_msg(conn))\n\nserver = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\nserver.bind((\"127.0.0.1\", 0))\nserver.listen(1)\nport = server.getsockname()[1]\nt = threading.Thread(target=serve, args=(server,))\nt.start()\n\nwith socket.create_connection((\"127.0.0.1\", port)) as c:\n    for msg in (b\"one\", b\"two\", b\"three\"):\n        send_msg(c, msg)\nt.join()\nserver.close()\n\nprint(got)          # Output: [b'one', b'two', b'three']",
